function generateInWorker(configuration){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(new Blob([MAP_WORKER_SOURCE],{type:'application/javascript'})),worker=new Worker(url);const finish=()=>{worker.terminate();URL.revokeObjectURL(url)};worker.onmessage=e=>{finish();e.data.error?reject(Error(e.data.error)):resolve(e.data.map)};worker.onerror=e=>{finish();reject(Error(e.message||'生成工作线程失败'))};worker.postMessage(configuration)})}
const $=id=>document.getElementById(id);const typeNames=['大堂','厨房','医疗室','储藏室','办公室','休息室','杂物间'];$('typeRules').innerHTML=typeNames.map((n,i)=>`<div class="type-row"><span>${n}</span><input aria-label="${n}最少数量" type="number" id="t${i}min" min="0" max="30" value="1"><input aria-label="${n}最多数量" type="number" id="t${i}max" min="0" max="30" value="${n==='储藏室'?6:4}"></div>`).join('')+'<p class="hint">楼梯间：每组 2 个 R13（上下层各一个）</p>';

let selectedCorr=null;
let map,floor='both',selected=0,sim=false,pos=0,key=false,loot=new Set(),visited=new Set([0]),done=false,message='';const colors={main:['#243d3a','#7fa99e'],explore:['#233449','#7997bf'],reward:['#443b28','#c6a467']};
function config(){let c={seed:$('seed').value,template:$('template').value,types:typeNames.map((name,i)=>({name,min:+$('t'+i+'min').value,max:+$('t'+i+'max').value}))};for(const id of ['explore','reward','stairs','minArea','maxArea','totalMin','totalMax'])c[id]=+$(id).value;return c}
async function generateNow(configuration){try{const next=await generateInWorker(configuration);map=next;selected=0;selectedCorr=null;sim=false;reset();$('error').textContent='';$('simulate').textContent='开始探索模拟';render()}catch(e){$('error').textContent=e.message+'。当前地图保留上一份有效结果。'}}
let generating=false;
function generate(){if(generating)return;generating=true;const configuration=config();$('generate').disabled=true;$('dice').disabled=true;$('generationStatus').textContent='正在按完整通道模块搜索并闭合接口，请稍候…';requestAnimationFrame(()=>setTimeout(async()=>{try{await generateNow(configuration)}finally{generating=false;$('generate').disabled=false;$('dice').disabled=false;$('generationStatus').textContent=''}},0))}
function reset(){pos=0;key=false;loot=new Set();visited=new Set([0]);done=false;message='点击相邻房间移动；通过楼梯可进入另一层。'}
function render(){if(!map)return;$('metrics').innerHTML=[['房间总数',map.rooms.length],['房间净面积',map.totalArea.toFixed(0)+' <small>m² / 两层合计</small>'],['通道净面积',map.corridorArea+' <small>m² / '+map.config.stairs+' 组楼梯</small>'],['完整通道 / 未接接口',map.corridorInstances.length+' / '+map.unconnectedPorts]].map(([a,b])=>`<div class="metric"><span>${a}</span><b>${b}</b></div>`).join('');$('layoutQuality').innerHTML=`<b>布局质量 · ${map.quality.withinTarget?'达到本轮目标':'仍有待优化项'}</b><span>最长无分支通道：${map.longestEmptyRun} 格（约 ${map.longestEmptyRun*2} m） / 目标 ≤24 格</span><span>最大房间直连组：${map.quality.maxDirectRooms} 间 / 目标 ≤4 间</span><span>仅服务单一直连组的通道面积：${map.unservedLoopArea} m²</span><small>接口连通校验与布局质量分开评价；本轮目标是评分目标，不保证每张图达标。</small>`;$('checks').innerHTML=map.checks.map(t=>'<div class="pass">✓ '+t+'</div>').join('')+['通道占房间与通道总净面积 '+Math.round(map.corridorArea/(map.totalArea+map.corridorArea)*100)+'%；已按通道面积和占地择优，仍可能存在外围绕行。',...map.warnings].map(t=>'<div class="warn">△ '+t+'</div>').join('');$('maps').style.gridTemplateColumns=floor==='both'?'':'1fr';$('maps').innerHTML=[0,1].filter(f=>floor==='both'||+floor===f).map(f=>drawFloor(f)).join('');document.querySelectorAll('.room').forEach(el=>{el.onclick=()=>choose(+el.dataset.id);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(+el.dataset.id)}}});document.querySelectorAll('.corridor').forEach(el=>{const inspect=()=>{selectedCorr=el.dataset.cid;render()};el.onclick=inspect;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect()}}});renderGroups();detail();simulation();renderCatalog()}
function drawFloor(f){
const S=25, B=map.bounds, rooms=map.rooms.filter(r=>r.floor===f), keyOf=p=>p.join(',');
const rects=(cells,fill)=>cells.map(([x,y])=>`<rect x="${x*S}" y="${y*S}" width="${S+.1}" height="${S+.1}" fill="${fill}"/>`).join('');
function walls(cells,color,width){const set=new Set(cells.map(keyOf));let d='';for(const [x,y] of cells){if(!set.has(keyOf([x,y-1])))d+=`M${x*S},${y*S}h${S}`;if(!set.has(keyOf([x+1,y])))d+=`M${(x+1)*S},${y*S}v${S}`;if(!set.has(keyOf([x,y+1])))d+=`M${x*S},${(y+1)*S}h${S}`;if(!set.has(keyOf([x-1,y])))d+=`M${x*S},${y*S}v${S}`}return `<path d="${d}" fill="none" stroke="${color}" stroke-width="${width}"/>`}
let s=`<div class="floor"><div class="floor-title"><b>${f+1}F / ${f?'上层 · 深入搜集':'首层 · 进入与回访'}</b><span>${map.template==='courtyard'?'环绕中庭':'双翼折返'} · ${rooms.length} 房间</span></div><div class="plan-scroll"><svg viewBox="${B.x*S} ${B.y*S} ${B.w*S} ${B.h*S}" style="min-width:620px;width:${$('mapZoom').value}%" aria-label="${f+1}层网格平面地图"><defs><pattern id="grid${f}" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#9ab7bd" stroke-opacity=".16" stroke-width=".7"/></pattern><pattern id="void${f}" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M0 8L8 0" stroke="#34474e" stroke-width="1"/></pattern></defs>`;
s+=rects(map.voidCells,`url(#void${f})`)+`<text x="12.5" y="12.5" text-anchor="middle" fill="#91a3aa" font-size="12">中庭 / 挑空</text>`;
for(const u of map.corridorInstances.filter(u=>u.floor===f)){s+=`<g class="corridor" tabindex="0" role="button" data-cid="${u.uid}" aria-label="${u.name} ${u.moduleId} ${u.area}平方米"><title>${u.moduleId} / ${u.uid} · ${u.name} · ${u.area} m² · ${u.rotation}°</title>`+rects(u.cells,selectedCorr===u.uid?'#405b61':'#293e47')+walls(u.cells,selectedCorr===u.uid?'#f1d79c':'#7b9ba7',selectedCorr===u.uid?3:1.6);for(const p of u.ports){const x=(p.inside[0]+p.outside[0]+1)/2*S,y=(p.inside[1]+p.outside[1]+1)/2*S,v=p.inside[0]!==p.outside[0];s+=`<path d="M${x-(v?0:10)} ${y-(v?10:0)}l${v?0:20} ${v?20:0}" stroke="#293e47" stroke-width="4"/>`}if($('moduleLabels').checked)s+=`<text x="${u.cx*S}" y="${u.cy*S+3}" text-anchor="middle" font-size="8" fill="#dbedf0" pointer-events="none">${u.moduleId}/${u.uid}</text>`;s+='</g>'}
for(const r of rooms){const [fill,stroke]=colors[r.role];s+=`<g class="room" role="button" tabindex="0" aria-label="${r.name} ${r.area}平方米" data-id="${r.id}"><title>${r.name} · ${r.area} m² · ${r.shape}</title>`+rects(r.cells,fill)+walls(r.cells,selected===r.id?'#fff1c9':map.roomGroups.find(g=>g.corridorId===selectedCorr)?.roomIds.includes(r.id)?'#78dfd5':stroke,selected===r.id?3:2)+`</g>`}
if($('grid').checked)s+=`<rect x="${B.x*S}" y="${B.y*S}" width="${B.w*S}" height="${B.h*S}" fill="url(#grid${f})" pointer-events="none"/>`;
if($('route').checked)for(const e of map.edges.filter(e=>e.kind==='main'&&map.rooms[e.a].floor===f)){const a=map.rooms[e.a],b=map.rooms[e.b];const insidePath=(r,out)=>{const start=[Math.floor(r.cx),Math.floor(r.cy)],allowed=new Set(r.cells.map(keyOf)),q=[start],prev=new Map([[keyOf(start),null]]);let end;for(const p of q){if(Math.abs(p[0]-out[0])+Math.abs(p[1]-out[1])===1){end=p;break}for(const [dx,dy] of [[1,0],[0,1],[-1,0],[0,-1]]){const next=[p[0]+dx,p[1]+dy],nk=keyOf(next);if(allowed.has(nk)&&!prev.has(nk)){prev.set(nk,p);q.push(next)}}}const result=[];while(end){result.push([end[0]+.5,end[1]+.5]);end=prev.get(keyOf(end))}return result.reverse()};const points=[...insidePath(a,e.path?.[0]||e.doors[0].outside),...(e.path||[]).map(([x,y])=>[x+.5,y+.5]),...insidePath(b,e.path?.at(-1)||e.doors[1].outside).reverse()];s+=`<polyline points="${points.map(p=>p.map(v=>v*S).join(',')).join(' ')}" fill="none" stroke="#a8e5b9" stroke-opacity=".7" stroke-width="2" stroke-dasharray="5 5" pointer-events="none"/>`}
for(const e of map.edges){if(e.kind==='stairs'){const r=rooms.find(r=>r.id===e.a||r.id===e.b);if(!r)continue;const [x,y]=e.landing;s+=`<g pointer-events="none"><rect x="${x*S-10}" y="${y*S-10}" width="20" height="20" fill="#b9c8c2"/><path d="M${x*S-7},${y*S-6}h14m-14 4h14m-14 4h14m-14 4h14" stroke="#2c3c37" stroke-width="1.5"/><text x="${x*S+14}" y="${y*S+4}" fill="#f4e7be" font-size="12">${e.label}</text></g>`;continue}if(map.rooms[e.a].floor!==f)continue;for(const d of e.doors||[]){const color=e.kind==='locked'?'#efbe62':e.kind==='loop'?'#cc9fde':'#c0e3df';s+=`<path d="M${d.x*S-(d.vertical?0:7)} ${d.y*S-(d.vertical?7:0)}l${d.vertical?0:14} ${d.vertical?14:0}" stroke="${color}" stroke-width="4" pointer-events="none"/>`;if(e.kind==='locked')s+=`<text x="${d.x*S+5}" y="${d.y*S-5}" fill="${color}" font-size="13" pointer-events="none">${sim&&key?'○':'▣'}</text>`}}
for(const r of rooms){s+=`<g pointer-events="none"><text x="${r.cx*S}" y="${r.cy*S-9}" text-anchor="middle" font-size="11" fill="#f0f4f0" paint-order="stroke" stroke="#19292d" stroke-width="3">${$('labels').checked?r.name:'R'+(r.id+1)}</text><text x="${r.cx*S}" y="${r.cy*S+6}" text-anchor="middle" font-size="10" fill="#c4d3d3">${r.moduleId} · ${r.area} m²</text><text x="${r.cx*S}" y="${r.cy*S+21}" text-anchor="middle" font-size="10" fill="#eacb8a">${r.exit?'◇ '+r.exit:''}${r.key?'⚿ 工具':''}${r.role==='reward'?'奖励':''}${$('route').checked&&r.id<10?' · '+(r.id+1):''}</text>${sim&&pos===r.id?`<circle cx="${r.cx*S}" cy="${r.cy*S-24}" r="5" fill="#e0ffe9" stroke="#111" stroke-width="2"/>`:''}</g>`}
return s+`</svg></div><div class="floor-caption">1 格 = 2 m · 基准格 25 px · ${f?'与首层同坐标':'房间实线为墙，短线为门'}</div></div>`;
}
function choose(id){selectedCorr=null;selected=id;if(sim&&!done&&id!==pos){const edge=map.edges.find(e=>e.a===pos&&e.b===id||e.b===pos&&e.a===id);if(!edge)message='只能前往直接连接的房间。跨层请点击「使用楼梯」。';else if(edge.kind==='locked'&&!key)message='门已锁定：先到 2F 获取探索工具。';else{pos=id;visited.add(id);if(map.rooms[id].key)key=true;if(map.rooms[id].role==='reward')loot.add(id);message=map.rooms[id].key?'已获得工具，现在可以返回首层解锁奖励房间。':'已进入 '+map.rooms[id].name;if(floor!=='both')floor=String(map.rooms[id].floor)}}render();tabs()}
function detail(){if(selectedCorr){const u=map.corridorInstances.find(u=>u.uid===selectedCorr),all=[...map.rooms,...map.corridorInstances];$('detail').innerHTML=`<b>${u.name}</b> · ${u.moduleId} / ${u.uid}<br>${u.floor+1}F · 旋转 ${u.rotation}° · ${u.area} m² · ${u.cells.length} 格<br>外接 ${u.w} × ${u.h} m · ${u.ports.length} 个固定接口，全部已连接<br>${map.roomGroups.some(g=>g.corridorId===u.uid)?'沿廊房间组 · 固定侧门贴接<br>':''}${u.ports.map(p=>{const owner=p.connectedTo.split(':')[0],target=all.find(t=>t.uid===owner);return p.id+'（'+(p.kind==='room'?'房间侧门':'接续口')+'） → '+target.name+' / '+p.connectedTo}).join('<br>')}`;return}let r=map.rooms[selected];$('detail').innerHTML=`<b>${r.name}</b> · ${r.moduleId} / ${r.shapeId} / ${r.rotation}° · ${r.floor+1}F · ${r.area.toFixed(1)} m²<br>${({main:'主路径',explore:'探索支路',reward:'奖励支路'})[r.role]} / ${r.shape} · ${r.cells.length} 格 · 实际 ${r.doorCount} 扇门<br>外接尺寸 ${r.w.toFixed(1)} × ${r.h.toFixed(1)} m（非净面积）<br><span class="detail-tags">${r.exit||''} ${r.key?'探索工具拾取点':''} ${r.role==='reward'?'工具解锁 · 奖励搜集点':''}</span><br>连接：${map.edges.filter(e=>e.a===r.id||e.b===r.id).map(e=>{let o=map.rooms[e.a===r.id?e.b:e.a];return o.name+(e.kind==='stairs'?'（楼梯 '+e.label+'）':e.kind==='locked'?'（锁门）':'')}).join('、')}`}
function simulation(){$('simulation').hidden=!sim;if(!sim)return;const stair=map.edges.find(e=>e.kind==='stairs'&&(e.a===pos||e.b===pos));$('simulation').innerHTML=`<b>${done?'撤离完成':'探索中'} · ${map.rooms[pos].floor+1}F / ${map.rooms[pos].name}</b>　工具：${key?'已获得':'未获得'}　奖励 ${loot.size}/${map.config.reward}　已访 ${visited.size}/${map.rooms.length}<br>${message}${!done&&stair?'<button id="useStair">使用楼梯 '+stair.label+'</button>':''}${!done&&map.rooms[pos].exit?'<button id="extract">从此处撤离</button>':''}<button id="resetSim">重新开始</button>`;if($('useStair'))$('useStair').onclick=()=>choose(stair.a===pos?stair.b:stair.a);if($('extract'))$('extract').onclick=()=>{done=true;message='已从'+map.rooms[pos].exit+'撤离，带出 '+loot.size+' 份奖励。';render()};$('resetSim').onclick=()=>{reset();render()}}
function tabs(){document.querySelectorAll('[data-floor]').forEach(b=>b.classList.toggle('active',b.dataset.floor===floor))}document.querySelectorAll('[data-floor]').forEach(b=>b.onclick=()=>{floor=b.dataset.floor;tabs();render()});$('generate').onclick=generate;$('dice').onclick=()=>{$('seed').value='RE-'+Math.random().toString(36).slice(2,8).toUpperCase();generate()};$('labels').onchange=render;$('grid').onchange=render;$('route').onchange=render;$('moduleLabels').onchange=render;$('mapZoom').onchange=render;$('simulate').onclick=()=>{sim=!sim;reset();$('simulate').textContent=sim?'结束探索模拟':'开始探索模拟';render()};$('export').onclick=()=>{if(!map)return;const blob=new Blob([JSON.stringify(map,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='extraction-map.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};generate();

function renderCatalog(){const roomCards=ModuleCatalog.rooms.map(m=>{const instances=map?.rooms.filter(r=>r.moduleId===m.id)||[],used=instances.length,w=Math.max(...m.cells.map(p=>p[0]))+1,h=Math.max(...m.cells.map(p=>p[1]))+1;const cells=m.cells.map(([x,y])=>`<rect x="${x*16+8}" y="${y*16+8}" width="16" height="16" fill="#334e49" stroke="#a2c4b6" stroke-width=".6"/>`).join('');const ports=m.ports.map(p=>{const x=(p.inside[0]+p.outside[0]+1)*8+8,y=(p.inside[1]+p.outside[1]+1)*8+8,v=p.inside[0]!==p.outside[0];return `<path d="M${x-(v?0:4)} ${y-(v?4:0)}l${v?0:8} ${v?8:0}" stroke="#f0c66a" stroke-width="3"/><text x="${x+3}" y="${y-4}" font-size="5" fill="#f0c66a">${p.id}</text>`}).join('');const counts=instances.map(r=>r.doorCount),range=used?(Math.min(...counts)===Math.max(...counts)?counts[0]:Math.min(...counts)+'–'+Math.max(...counts)):'—';return `<article class="asset-card"><svg viewBox="0 0 84 84" role="img" aria-label="${m.id} ${m.type} ${m.shape}轮廓">${cells}${ports}</svg><b>${m.id} ${m.type}</b><small>${m.shape} · ${w} × ${h} 格${m.shape==='S6'?'（L 形）':''}</small><small>${m.area} m² · 外接 ${w*2} × ${h*2} m</small><span>固定 ${m.doorCount} 扇门 · 本图 ${used} 个</span><small>门位不变 · 仅允许整体旋转</small></article>`});const corridorCards=ModuleCatalog.corridors.map(m=>{const w=Math.max(...m.cells.map(p=>p[0]))+1,h=Math.max(...m.cells.map(p=>p[1]))+1;return `<article class="asset-card"><svg viewBox="-1 -1 9 9" role="img" aria-label="${m.id} ${m.name}">${m.cells.map(([x,y])=>`<rect x="${x}" y="${y}" width="1" height="1" fill="#344c59" stroke="#9db1bb" stroke-width=".04"/>`).join('')}${m.ports.map(p=>{const x=(p.inside[0]+p.outside[0]+1)/2,y=(p.inside[1]+p.outside[1]+1)/2,v=p.inside[0]!==p.outside[0];return `<path d="M${x-(v?0:.3)} ${y-(v?.3:0)}l${v?0:.6} ${v?.6:0}" stroke="${p.kind==='room'?'#f0c66a':'#73cadc'}" stroke-width=".16"/>`}).join('')}</svg><b>${m.id} ${m.name}</b><small>外接 ${w} × ${h} 格 · ${m.cells.length} 格占地</small><small>${m.area} m² · ${m.ports.filter(p=>p.kind==='continuation').length} 接续口 / ${m.ports.filter(p=>p.kind==='room').length} 房门</small><small>${m.purpose}</small><span>本图 ${map?.assetUsage.corridors.find(u=>u.moduleId===m.id).count||0} 个完整实例</span></article>`});$('roomCatalog').innerHTML=roomCards.join('');$('corridorCatalog').innerHTML=corridorCards.join('')}


function renderGroups(){const el=$('roomGroups');el.innerHTML=map.roomGroups.map(g=>`<button class="group-card" data-group="${g.corridorId}"><b>${g.floor+1}F · ${g.moduleId} / ${g.corridorId}</b><span>${g.roomIds.map(id=>map.rooms[id].name).join('、')}</span></button>`).join('')||'<p class="hint">当前规则没有需要侧门组团的支路房间。</p>';el.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{selectedCorr=b.dataset.group;render();$('detail').scrollIntoView({block:'center',behavior:'smooth'})})}
